                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { Dimensions } from 'react-native';\n\nconst SCREEN_WIDTH = Dimensions.get('window').width;\n\n// 自機移動 System\nexport const MovePlayerSystem = (\n  entities: any,\n  { touches }: any\n) => {\n  const player = entities.player;\n\n  touches\n    .filter((t: any) => t.type === 'move')\n    .forEach((t: any) => {\n      // タッチ位置に自機を追従\n      let newX = t.event.pageX - player.size.width / 2;\n      // 画面端の制限\n      newX = Math.max(0, Math.min(newX, SCREEN_WIDTH - player.size.width));\n      player.position.x = newX;\n    });\n\n  return entities;\n};", 'filename' => 'systems/MovePlayerSystem.ts'],
                    ['type' => 'heading', 'level' => 3, 'text' => 'タッチイベントの種類'],
                    ['type' => 'list', 'items' => ['start: 指が画面に触れた瞬間', 'move: 指が画面上を移動中', 'end: 指が画面から離れた瞬間', 'press: 短いタップ（タッチして離す）']],
                    ['type' => 'heading', 'level' => 3, 'text' => '弾の発射 System'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import BulletRenderer from '../renderers/BulletRenderer';\n\nlet bulletCount = 0;\nconst FIRE_INTERVAL = 300; // 発射間隔(ms)\nlet lastFireTime = 0;\n\nexport const FireSystem = (\n  entities: any,\n  { touches, time }: any\n) => {\n  // タップで発射（連射制限あり）\n  const now = time.current;\n  const taps = touches.filter((t: any) => t.type === 'press');\n\n  if (taps.length > 0 && now - lastFireTime > FIRE_INTERVAL) {\n    lastFireTime = now;\n    const player = entities.player;\n    const bulletId = `bullet_\${bulletCount++}`;\n\n    entities[bulletId] = {\n      position: {\n        x: player.position.x + player.size.width / 2 - 2,\n        y: player.position.y - 15,\n      },\n      size: { width: 4, height: 12 },\n      speed: 8,\n      active: true,\n      renderer: <BulletRenderer />,\n    };\n  }\n\n  return entities;\n};", 'filename' => 'systems/FireSystem.tsx'],
                    ['type' => 'text', 'text' => 'ECS パターンでは System が新しいエンティティを entities オブジェクトに追加することで、動的にゲームオブジェクトを生成できます。弾のように大量に生成・削除されるオブジェクトの管理に適しています。'],
                    ['type' => 'comparison', 'title' => '動的オブジェクト生成の比較', 'react' => "// コースA: useState で配列管理\nconst [bullets, setBullets] = useState([]);\n\nconst fire = () => {\n  setBullets(prev => [...prev, {\n    id: nextId++,\n    x: playerX,\n    y: playerY,\n  }]);\n};", 'reactNative' => "// コースB: entities に追加\nconst FireSystem = (entities, args) => {\n  entities[`bullet_\${id++}`] = {\n    position: { x, y },\n    speed: 8,\n    renderer: <BulletRenderer />,\n  };\n  return entities;\n};"],
                    ['type' => 'quiz', 'questions' => [
                        ['question' => 'GameEngine が System に渡すタッチイベントの配列名は？', 'options' => ['touches', 'events', 'gestures', 'inputs'], 'correct' => 0, 'explanation' => 'System の第2引数の touches 配列にタッチイベントが格納されます。'],
                        ['question' => 'ECS で新しいゲームオブジェクト（弾など）を動的に追加する方法は？', 'options' => ['entities オブジェクトに新しいキーで追加', 'setState で配列に追加', 'GameEngine の API を呼ぶ', 'コンストラクタで new する'], 'correct' => 0, 'explanation' => 'System 内で entities[newKey] = {...} として追加し、return entities すれば新しいエンティティが描画されます。'],
                    ]],
                ],
            ],
            [
                'number' => 7,
                'title' => '弾の発射システム',
                'summary' => '弾エンティティの動的生成と移動Systemを実装します。',
                'content' => [
                    ['type' => 'heading', 'level' => 2, 'text' => '弾の移動 System'],
                    ['type' => 'text', 'text' => '弾は毎フレーム上方向に移動します。画面外に出た弾はエンティティから削除してメモリを節約します。'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "export const MoveBulletsSystem = (entities: any, { time }: any) => {\n  const bulletKeys = Object.keys(entities).filter(key => key.startsWith('bullet_'));\n\n  bulletKeys.forEach(key => {\n    const bullet = entities[key];\n    if (!bullet.active) return;\n\n    // 上方向に移動（delta で速度補正）\n    bullet.position.y -= bullet.speed * (time.delta / 16);\n\n    // 画面外に出たら削除\n    if (bullet.position.y < -20) {\n      delete entities[key];\n    }\n  });\n\n  return entities;\n};", 'filename' => 'systems/MoveBulletsSystem.ts'],
                    ['type' => 'heading', 'level' => 3, 'text' => '弾のレンダラー'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { View, StyleSheet } from 'react-native';\n\nexport default function BulletRenderer({ position, size }: any) {\n  return (\n    <View\n      style={[\n        styles.bullet,\n        {\n          left: position.x,\n          top: position.y,\n          width: size.width,\n          height: size.height,\n        },\n      ]}\n    />\n  );\n}\n\nconst styles = StyleSheet.create({\n  bullet: {\n    position: 'absolute',\n    backgroundColor: '#ff0',\n    borderRadius: 2,\n  },\n});", 'filename' => 'renderers/BulletRenderer.tsx'],
                    ['type' => 'heading', 'level' => 3, 'text' => 'GameEngine に System を登録'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { GameEngine } from 'react-native-game-engine';\nimport { createEntities } from '../entities';\nimport { MovePlayerSystem } from '../systems/MovePlayerSystem';\nimport { FireSystem } from '../systems/FireSystem';\nimport { MoveBulletsSystem } from '../systems/MoveBulletsSystem';\n\nexport default function GameScreen() {\n  return (\n    <GameEngine\n      style={{ flex: 1, backgroundColor: '#000' }}\n      entities={createEntities()}\n      systems={[\n        MovePlayerSystem,   // 1. 自機の移動\n        FireSystem,          // 2. 弾の発射\n        MoveBulletsSystem,   // 3. 弾の移動\n      ]}\n    />\n  );\n}", 'filename' => 'screens/GameScreen.tsx'],
                    ['type' => 'text', 'text' => 'systems 配列に登録した順序で System が毎フレーム実行されます。順序が重要な場合があります（例：移動→衝突判定→描画）。'],
                    ['type' => 'tip', 'text' => 'Laravel のミドルウェアパイプラインと同様に、systems は配列の順序で実行されます。「入力処理→移動→衝突判定→クリーンアップ」の順で並べるのが一般的です。'],
                    ['type' => 'warning', 'text' => 'delete entities[key] でエンティティを削除すると、対応するレンダラーも自動的に画面から消えます。ただし、大量に delete を繰り返すとパフォーマンスに影響する場合があります。'],
                    ['type' => 'quiz', 'questions' => [
                        ['question' => 'systems 配列の実行順序は？', 'options' => ['配列のインデックス順（先頭から）', 'ランダム', '並列実行', '逆順'], 'correct' => 0, 'explanation' => 'systems は配列の先頭から順に毎フレーム実行されます。Laravel のミドルウェアと同様に順序が重要です。'],
                        ['question' => '画面外に出た弾エンティティを削除する方法は？', 'options' => ['delete entities[key]', 'entities[key] = null', 'entities.remove(key)', 'entities[key].destroy()'], 'correct' => 0, 'explanation' => 'JavaScript の delete 演算子でエンティティを削除すると、GameEngine が自動的にレンダリングから除外します。'],
                    ]],
