            [
                'number' => 8,
                'title' => '敵エンティティと移動',
                'summary' => '敵の一括管理と移動パターンSystemを実装します。',
                'content' => [
                    ['type' => 'heading', 'level' => 2, 'text' => '敵エンティティの一括生成'],
                    ['type' => 'text', 'text' => '5行×8列の敵をエンティティとして一括生成します。各敵には一意のキー名を付けて管理します。'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { Dimensions } from 'react-native';\nimport EnemyRenderer from '../renderers/EnemyRenderer';\n\nconst SCREEN_WIDTH = Dimensions.get('window').width;\nconst ENEMY_ROWS = 5;\nconst ENEMY_COLS = 8;\nconst ENEMY_SIZE = 30;\nconst ENEMY_GAP = 10;\n\nexport function createEnemyEntities(): Record<string, any> {\n  const entities: Record<string, any> = {};\n  const startX = (SCREEN_WIDTH - ENEMY_COLS * (ENEMY_SIZE + ENEMY_GAP)) / 2;\n\n  for (let row = 0; row < ENEMY_ROWS; row++) {\n    for (let col = 0; col < ENEMY_COLS; col++) {\n      const key = `enemy_\${row}_\${col}`;\n      entities[key] = {\n        position: {\n          x: startX + col * (ENEMY_SIZE + ENEMY_GAP),\n          y: 80 + row * (ENEMY_SIZE + ENEMY_GAP),\n        },\n        size: { width: ENEMY_SIZE, height: ENEMY_SIZE },\n        type: Math.min(row, 2),\n        alive: true,\n        renderer: <EnemyRenderer />,\n      };\n    }\n  }\n\n  return entities;\n}\n\n// createEntities に統合\nexport function createEntities() {\n  return {\n    player: { /* ... */ },\n    ...createEnemyEntities(),\n    // ゲーム全体の状態を管理するメタエンティティ\n    gameState: {\n      direction: 1,  // 1: 右, -1: 左\n      speed: 1,\n      renderer: null, // 描画なし\n    },\n  };\n}", 'filename' => 'entities/index.tsx'],
                    ['type' => 'heading', 'level' => 3, 'text' => '敵レンダラー'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { View, Text, StyleSheet } from 'react-native';\n\nconst ENEMY_DESIGNS = ['👾', '🛸', '👽'];\n\nexport default function EnemyRenderer({ position, size, type, alive }: any) {\n  if (!alive) return null;\n\n  return (\n    <View style={[\n      styles.container,\n      { left: position.x, top: position.y, width: size.width, height: size.height },\n    ]}>\n      <Text style={styles.emoji}>{ENEMY_DESIGNS[type] || '👾'}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { position: 'absolute', alignItems: 'center', justifyContent: 'center' },\n  emoji: { fontSize: 24 },\n});", 'filename' => 'renderers/EnemyRenderer.tsx'],
                    ['type' => 'heading', 'level' => 3, 'text' => '敵の一斉移動 System'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { Dimensions } from 'react-native';\n\nconst SCREEN_WIDTH = Dimensions.get('window').width;\nconst ENEMY_SPEED = 1.5;\nconst DROP_DISTANCE = 20;\n\nexport const MoveEnemiesSystem = (entities: any, { time }: any) => {\n  const gameState = entities.gameState;\n  const enemyKeys = Object.keys(entities).filter(k => k.startsWith('enemy_'));\n  const aliveEnemies = enemyKeys.filter(k => entities[k].alive);\n\n  if (aliveEnemies.length === 0) return entities;\n\n  // 端に到達したか確認\n  let hitEdge = false;\n  aliveEnemies.forEach(key => {\n    const enemy = entities[key];\n    if (enemy.position.x + enemy.size.width >= SCREEN_WIDTH - 10 && gameState.direction > 0) {\n      hitEdge = true;\n    }\n    if (enemy.position.x <= 10 && gameState.direction < 0) {\n      hitEdge = true;\n    }\n  });\n\n  // 端に到達したら方向反転＋1段下降\n  if (hitEdge) {\n    gameState.direction *= -1;\n    aliveEnemies.forEach(key => {\n      entities[key].position.y += DROP_DISTANCE;\n    });\n    // 速度を少し上げる（難易度上昇）\n    gameState.speed = Math.min(gameState.speed + 0.1, 4);\n  }\n\n  // 全敵を移動\n  const moveAmount = ENEMY_SPEED * gameState.speed * gameState.direction * (time.delta / 16);\n  aliveEnemies.forEach(key => {\n    entities[key].position.x += moveAmount;\n  });\n\n  return entities;\n};", 'filename' => 'systems/MoveEnemiesSystem.ts'],
                    ['type' => 'text', 'text' => 'gameState エンティティを使ってゲーム全体の状態（方向、速度）を管理します。renderer: null にすれば描画されないため、メタデータの管理に使えます。'],
                    ['type' => 'tip', 'text' => 'gameState のような「描画しないエンティティ」はゲーム全体の状態管理に便利です。Laravel のシングルトンサービスに似た役割で、複数の System 間で状態を共有できます。'],
                    ['type' => 'quiz', 'questions' => [
                        ['question' => 'renderer: null のエンティティの役割は？', 'options' => ['描画なしでゲーム状態のメタデータを管理する', '非表示の敵を管理する', 'エラーを防ぐダミー', 'パフォーマンス最適化'], 'correct' => 0, 'explanation' => 'renderer: null のエンティティは画面に描画されず、ゲーム全体の状態（方向、速度など）を複数の System 間で共有するために使います。'],
                        ['question' => '敵の移動速度を徐々に上げる（難易度上昇）にはどうする？', 'options' => ['gameState.speed を段階的に増加させる', '新しい System を追加する', '敵エンティティを毎フレーム再作成する', 'setInterval の間隔を変える'], 'correct' => 0, 'explanation' => 'gameState エンティティの speed 値を段階的に上げることで、同じ System のまま難易度を動的に変更できます。'],
                    ]],
                ],
            ],
            [
                'number' => 9,
                'title' => '衝突判定システム',
                'summary' => 'Collision Detection Systemを実装し、弾と敵の当たり判定を処理します。',
                'content' => [
                    ['type' => 'heading', 'level' => 2, 'text' => '衝突判定 System の実装'],
                    ['type' => 'text', 'text' => 'ECS パターンでは衝突判定も独立した System として実装します。ここでは AABB（Axis-Aligned Bounding Box）という矩形同士の重なりを判定するシンプルな方法を使います。弾と敵の衝突、敵と自機の接近をチェックします。'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "// utils/collision.ts\nexport interface Rect {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n}\n\nexport function isColliding(a: Rect, b: Rect): boolean {\n  return (\n    a.x < b.x + b.width &&\n    a.x + a.width > b.x &&\n    a.y < b.y + b.height &&\n    a.y + a.height > b.y\n  );\n}\n\nexport function entityToRect(entity: any): Rect {\n  return {\n    x: entity.position.x,\n    y: entity.position.y,\n    width: entity.size.width,\n    height: entity.size.height,\n  };\n}", 'filename' => 'utils/collision.ts'],
                    ['type' => 'heading', 'level' => 3, 'text' => '衝突判定 System'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { isColliding, entityToRect } from '../utils/collision';\nimport { Dimensions } from 'react-native';\n\nconst SCREEN_HEIGHT = Dimensions.get('window').height;\n\nexport const CollisionSystem = (\n  entities: any,\n  { dispatch }: any\n) => {\n  const bulletKeys = Object.keys(entities).filter(k => k.startsWith('bullet_'));\n  const enemyKeys = Object.keys(entities).filter(k => k.startsWith('enemy_'));\n\n  // 弾 vs 敵の衝突判定\n  bulletKeys.forEach(bulletKey => {\n    const bullet = entities[bulletKey];\n    if (!bullet) return;\n\n    for (const enemyKey of enemyKeys) {\n      const enemy = entities[enemyKey];\n      if (!enemy || !enemy.alive) continue;\n\n      if (isColliding(entityToRect(bullet), entityToRect(enemy))) {\n        // 敵を倒す\n        enemy.alive = false;\n        // 弾を削除\n        delete entities[bulletKey];\n        // スコア加算イベント\n        const points = (3 - enemy.type) * 10;\n        dispatch({ type: 'score', points });\n        break; // 1つの弾で1体の敵のみ倒す\n      }\n    }\n  });\n\n  // 敵が画面下端に到達したらゲームオーバー\n  const aliveEnemies = enemyKeys.filter(k => entities[k]?.alive);\n  const reachedBottom = aliveEnemies.some(\n    k => entities[k].position.y + entities[k].size.height >= SCREEN_HEIGHT - 120\n  );\n\n  if (reachedBottom) {\n    dispatch({ type: 'game-over' });\n  }\n\n  // 全敵撃破チェック\n  if (aliveEnemies.length === 0 && enemyKeys.length > 0) {\n    dispatch({ type: 'game-clear' });\n  }\n\n  return entities;\n};", 'filename' => 'systems/CollisionSystem.ts'],
                    ['type' => 'text', 'text' => '衝突判定 System は他の System（移動など）の後に実行されるよう、systems 配列の後方に配置します。Laravel のミドルウェアの実行順序と同じように、処理の依存関係を考慮して順序を決めます。'],
                    ['type' => 'heading', 'level' => 3, 'text' => 'System の実行順序'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "systems={[\n  MovePlayerSystem,    // 1. 自機移動\n  FireSystem,           // 2. 弾の発射\n  MoveBulletsSystem,    // 3. 弾の移動\n  MoveEnemiesSystem,    // 4. 敵の移動\n  CollisionSystem,      // 5. 衝突判定（移動後に実行）\n]}"],
                    ['type' => 'tip', 'text' => 'System の実行順序は「入力 → 移動 → 衝突判定 → 結果処理」が定番です。Laravel のリクエストライフサイクル（ミドルウェア → コントローラー → レスポンス）に対応する概念です。'],
                    ['type' => 'quiz', 'questions' => [
                        ['question' => '衝突判定 System はいつ実行すべき？', 'options' => ['移動 System の後', '移動 System の前', '最初に実行', '順序は関係ない'], 'correct' => 0, 'explanation' => '衝突判定は全オブジェクトの移動が完了した後に実行することで、正確な判定ができます。'],
                        ['question' => '衝突判定で使用した AABB は何の略？', 'options' => ['Axis-Aligned Bounding Box', 'Advanced Automatic Boundary Builder', 'Absolute Area Bounding Box', 'Aligned Axis Base Box'], 'correct' => 0, 'explanation' => 'AABB = Axis-Aligned Bounding Box（軸に沿った境界ボックス）。矩形同士の重なりを4条件で判定する最もシンプルな衝突判定です。'],
                    ]],
                ],
            ],
            [
                'number' => 10,
                'title' => 'ゲーム状態管理',
                'summary' => 'スコア、ライフ、ゲームオーバー処理とイベントディスパッチを統合します。',
                'content' => [
                    ['type' => 'heading', 'level' => 2, 'text' => 'GameEngine のイベント処理で状態管理'],
                    ['type' => 'text', 'text' => 'System から dispatch したイベントを GameEngine の onEvent で受け取り、React の state で UI を更新します。ゲームロジック（System）と UI 表示（React）を綺麗に分離できます。'],
                    ['type' => 'code', 'language' => 'tsx', 'code' => "import { useState, useRef, useCallback } from 'react';\nimport { View, Text, TouchableOpacity, StyleSheet, Dimensions } from 'react-native';\nimport { GameEngine } from 'react-native-game-engine';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { createEntities } from '../entities';\nimport { MovePlayerSystem } from '../systems/MovePlayerSystem';\nimport { FireSystem } from '../systems/FireSystem';\nimport { MoveBulletsSystem } from '../systems/MoveBulletsSystem';\nimport { MoveEnemiesSystem } from '../systems/MoveEnemiesSystem';\nimport { CollisionSystem } from '../systems/CollisionSystem';\n\nexport default function GameScreen({ navigation }: any) {\n  const engineRef = useRef<any>(null);\n  const [score, setScore] = useState(0);\n  const [lives, setLives] = useState(3);\n  const [gameOver, setGameOver] = useState(false);\n  const [gameClear, setGameClear] = useState(false);\n  const [running, setRunning] = useState(true);\n\n  const saveHighScore = async (finalScore: number) => {\n    const current = await AsyncStorage.getItem('highScore');\n    if (!current || finalScore > parseInt(current)) {\n      await AsyncStorage.setItem('highScore', finalScore.toString());\n    }\n  };\n\n  const handleEvent = useCallback(async (event: any) => {\n    switch (event.type) {\n      case 'score':\n        setScore(prev => prev + event.points);\n        break;\n      case 'player-hit':\n        setLives(prev => {\n          const newLives = prev - 1;\n          if (newLives <= 0) {\n            setGameOver(true);\n            setRunning(false);\n          }\n          return newLives;\n        });\n        break;\n      case 'game-over':\n        setGameOver(true);\n        setRunning(false);\n        saveHighScore(score);\n        break;\n      case 'game-clear':\n        setGameClear(true);\n        setRunning(false);\n        saveHighScore(score);\n        break;\n    }\n  }, [score]);\n\n  const restart = () => {\n    setScore(0);\n    setLives(3);\n    setGameOver(false);\n    setGameClear(false);\n    setRunning(true);\n    engineRef.current?.swap(createEntities());\n  };\n\n  return (\n    <View style={styles.container}>\n      {/* ヘッダー */}\n      <View style={styles.header}>\n        <Text style={styles.headerText}>SCORE: {score}</Text>\n        <Text style={styles.headerText}>{'♥'.repeat(lives)}</Text>\n      </View>\n\n      {/* ゲーム画面 */}\n      <GameEngine\n        ref={engineRef}\n        style={styles.game}\n        entities={createEntities()}\n        systems={[\n          MovePlayerSystem,\n          FireSystem,\n          MoveBulletsSystem,\n          MoveEnemiesSystem,\n          CollisionSystem,\n        ]}\n        running={running}\n        onEvent={handleEvent}\n      />\n\n      {/* ゲームオーバー/クリア モーダル */}\n      {(gameOver || gameClear) && (\n        <View style={styles.overlay}>\n          <Text style={styles.overlayTitle}>\n            {gameClear ? 'STAGE CLEAR!' : 'GAME OVER'}\n          </Text>\n          <Text style={styles.overlayScore}>SCORE: {score}</Text>\n          <TouchableOpacity style={styles.button} onPress={restart}>\n            <Text style={styles.buttonText}>RETRY</Text>\n          </TouchableOpacity>\n          <TouchableOpacity onPress={() => navigation.navigate('Home')}>\n            <Text style={styles.homeLink}>HOME</Text>\n          </TouchableOpacity>\n        </View>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: '#000' },\n  header: { flexDirection: 'row', justifyContent: 'space-between', padding: 10, paddingTop: 50 },\n  headerText: { color: '#fff', fontSize: 16, fontWeight: 'bold' },\n  game: { flex: 1 },\n  overlay: { ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(0,0,0,0.8)', alignItems: 'center', justifyContent: 'center' },\n  overlayTitle: { fontSize: 36, fontWeight: 'bold', color: '#0f0', marginBottom: 20 },\n  overlayScore: { fontSize: 24, color: '#fff', marginBottom: 30 },\n  button: { borderWidth: 2, borderColor: '#0f0', paddingHorizontal: 40, paddingVertical: 12, borderRadius: 4, marginBottom: 15 },\n  buttonText: { fontSize: 20, fontWeight: 'bold', color: '#0f0' },\n  homeLink: { fontSize: 16, color: '#888', marginTop: 10 },\n});", 'filename' => 'screens/GameScreen.tsx'],
                    ['type' => 'heading', 'level' => 3, 'text' => 'running prop でゲームの一時停止'],
